import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectName, setSubjectName] = useState('');

  const fetchSubjects = () => {
    axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  };

  useEffect(() => { fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { subject_name: subjectName }).then(() => {
      fetchSubjects();
      setSubjectName('');
    });
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2 style={{ color: '#15803d' }}>📚 Manage Subjects</h2>
      
      {/* Subject Input Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: '20px', display: 'flex', gap: '10px' }}>
        <input 
          type="text" placeholder="Add new subject..." value={subjectName} 
          onChange={(e) => setSubjectName(e.target.value)} required 
          style={{ padding: '10px', width: '250px', borderRadius: '5px', border: '1px solid #ccc' }}
        />
        <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>+ Add Subject</button>
      </form>

      {/* Subject Table */}
      <table style={{ width: '100%', borderCollapse: 'collapse', backgroundColor: 'white' }}>
        <thead>
          <tr style={{ backgroundColor: '#f1f5f9' }}>
            <th style={{ padding: '12px', border: '1px solid #ddd' }}>ID</th>
            <th style={{ padding: '12px', border: '1px solid #ddd' }}>Subject Name</th>
            <th style={{ padding: '12px', border: '1px solid #ddd' }}>Status</th>
          </tr>
        </thead>
        <tbody>
          {subjects.map(s => (
            <tr key={s.id}>
              <td style={{ padding: '12px', border: '1px solid #ddd', textAlign: 'center' }}>{s.id}</td>
              <td style={{ padding: '12px', border: '1px solid #ddd' }}>{s.subject_name}</td>
              <td style={{ padding: '12px', border: '1px solid #ddd', color: '#15803d', fontWeight: 'bold' }}>Active ✅</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
